"""
apply_day11.py  -  ONE FILE that upgrades your production-rag project to Day 11.

HOW TO USE (Windows CMD), from inside your production-rag folder:
    .venv\\Scripts\\activate
    python apply_day11.py

What it does:
  1. Backs up every file it is about to change into  _backup_before_day11\\
  2. Writes all Day 1-11 code, tests, scripts, evals, docs, and a GitHub
     Actions workflow (.github/workflows/ci.yml) into this folder
  3. NEVER touches: .env, .venv, app\\storage, evals\\reports
  4. Runs  pip install -r requirements.txt   (adds pyyaml explicitly)
  5. Runs  python scripts\\verify_day11.py  (tests + CI config check + a real cost-bounded eval)

After this: push to GitHub and add an OPENAI_API_KEY repo secret (Settings
-> Secrets and variables -> Actions) if you want the live-eval CI job to
run for real on pushes to main. The free test job runs either way.

Options:
    --no-install    skip pip install
    --no-verify     skip the verification run
    --offline       verification without a live call (free either way for most of Day 11)
    --force         run even if this does not look like a production-rag folder
"""

